"""Small pure helpers for planning a batch-preparation shopping list."""


def aggregate_items(rows):
    """Consolidate the shopping rows while retaining their encounter order."""
    totals = {}
    for row in rows:
        item = row["item"]
        totals[item] = totals.get(item, 0) + row["units"]
    return [{"item": item, "units": units} for item, units in totals.items()]


def split_batches(amounts, limit):
    """Partition each preparation amount into its own sequence of batches."""
    result = []
    for amount in amounts:
        full, tail = divmod(amount, limit)
        batches = [limit] * full
        if tail:
            batches.append(tail)
        result.append(batches)
    return result


def plan_shortfall(requested, available):
    """Return the remaining units to buy for each requested ingredient."""
    result = {}
    for item, units in requested.items():
        result[item] = max(units - available.get(item, 0), 0)
    return result


def rescale_units(recipe, from_servings, to_servings):
    """Rescale indivisible ingredient units for a new serving count."""
    result = {}
    for item, units in recipe.items():
        result[item] = (units * to_servings + from_servings - 1) // from_servings
    return result


def substitute_items(items, replacements):
    """Apply the selected ingredient substitutions simultaneously."""
    result = []
    for item in items:
        first = replacements.get(item, item)
        result.append(replacements.get(first, first))
    return result
